/**
 * 获取预设关卡数据（深拷贝）
 * @param {number} level 关卡号（16-100）
 * @returns {object|null} 关卡数据或 null
 */
export function getPresetLevel(level) {
  const data = PRESET_LEVELS[level];
  if (!data) return null;
  return JSON.parse(JSON.stringify(data));
}

export function hasPresetLevel(level) {
  return !!PRESET_LEVELS[level];
}

export function getPresetLevelRange() {
  return { min: 16, max: 100 };
}
